// === Tab: mySketch ===
/**
 * Doo-doo-doodles
 * For the Weekly Creative Coding Challenge «My kid could draw that»
 * Join the discord! https://discord.gg/PrnrhZQrb9
 *
 * This sketch draws some doodle, taken from the Google QuickDraw dataset https://github.com/googlecreativelab/quickdraw-dataset
 * I took a random sample of some of their categories, only selecting from the recognized drawings
 * (after the neural network processing).
 *
 * The sketches are then decomposed into triangle approximations using decomp https://github.com/schteppe/poly-decomp.js/
 * for collision detection and placement (note that due to the way the lines are drawn,
 * the shapes are not always perfect), and then the sketch tries to place them on the canvas,
 * drawing one stroke at a time.
 *
 * Effect for scribble lines using the p5.scribble library https://github.com/generative-light/p5.scribble.js/
 * Geometry functions courtesy of ChatGPT
 *
 * Even though is a semi-naive packing algorithm, it becomes very slow towards the end. I wanted to experiment
 * with workers to have the placement being independent from the draw loop, but it will have to wait to another time
 */


let drawings = []
let randomDrawing
let scribble
let cw, ch

let doodles = []
let totalTriangles = []
let strokeIndex = 0
let failedAttempts = 0
let MAX_POSITION_TRIES = 100
let MAX_FAILED_ATTEMPTS = 20
let DEBUG = false

let palette = [
  "#FF6E4A", "#FFD700", "#1CAC78", "#1F75FE", "#926EAE",
  "#0c5e50", "#EE204D", "#36241c", "#FFAACC", "#aa8b7e"
]

function preload() {
  drawings = loadStrings("https://openprocessing.org/sketch/2363801/files/doodles.ndjson")
}

function setup() {
  cw = windowWidth
  ch = windowHeight
  createCanvas(cw, ch)
  scribble = new Scribble()
  scribble.bowing = 2
  scribble.roughness = 0.4
  scribble.maxOffset = 3

  texture = granulate(120)
  generateDoodle()
  frameRate(10)
}

function draw () {
  background(250)
  for (let i = 0; i < doodles.length; i++) {
    if (i === doodles.length - 1) {
      // Draw only the number of strokes that have been drawn so far
      drawDoodle(doodles[i], strokeIndex)
      // If all strokes are drawn, generate a new doodle
      if (strokeIndex < doodles[i].drawing.length) {
        strokeIndex++
      } else {
        let newDoodle = generateDoodle()
        if (newDoodle) {
          strokeIndex = 0
        } else {
          failedAttempts++
          // If failed attempts exceed a threshold, clear the canvas and start over
          if (failedAttempts > MAX_FAILED_ATTEMPTS) {
            failedAttempts = 0
            doodles = []
            totalTriangles = []
            generateDoodle()
          }
        }
      }
    } else {
      drawDoodle(doodles[i])
    }
  }
  image(texture, 0, 0, cw, cw)
}

// On mouse click, pause or resume the sketch loop
function mousePressed() {
  if (isLooping()) {
    noLoop()
  } else {
    loop()
  }
}

function keyPressed() {
  if (key === "d" || key === "D") {
    DEBUG = !DEBUG
  }
  if (key === "s" || key === "S") {
    saveCanvas("doodle-" + Date.now(), "png")
  }
}



let getRandomDoodle = () => {
  let numTries = MAX_POSITION_TRIES
  let isValidDoodle = false
  let randomIndex, doodle

  let _wG_1 = 0; while ((!isValidDoodle && numTries > 0) && ++_wG_1 < 20000) {
    // Pick a random doodle, scale and rotate it, then calculate additional geometry info
    // TODO: Make scale based on how much space is left on the canvas
    randomIndex = floor(random(drawings.length))
    doodle = JSON.parse(drawings[randomIndex])
    doodle.drawing = scaleDoodle(doodle, random(0.3, 2))
    doodle.bbox = getBBox(doodle.drawing)
    doodle.drawing = rotateDoodle(doodle, random(TWO_PI))

    // Translate the doodle randomly within the canvas, use the bounding box to calculate the offset
    let xOff = random(0, cw - doodle.bbox.maxX)
    let yOff = random(0, ch - doodle.bbox.maxY)
    doodle.drawing = translateDoodle(doodle, xOff, yOff)
    doodle.bbox = getBBox(doodle.drawing) // Readjust the bounding box

    doodle.triangles = generateTriangles(doodle)
    doodle.color = random(palette)

    // Check if the doodle is valid
    if (canPlaceDoodle(doodle)) {
      isValidDoodle = true
      // Add the doodle triangles to the polyShapes array
      totalTriangles.push(...doodle.triangles)
    } else {
      numTries--
    }
  }
  if (numTries === 0) {
    return null
  } else {
    return doodle
  }
}

let canPlaceDoodle = (doodle) => {
  // Check for overlap with existing shapes
  for (let triangle of doodle.triangles) {
    for (let shape of totalTriangles) {
      if (trianglesOverlap(triangle, shape)) {
        return false
      }
    }
  }
  return true
}

let drawPoly = (polygon) => {
  beginShape()
  for (let i = 0; i < polygon.length; i++) {
    let point = polygon[i]
    vertex(point[0], point[1])
  }
  endShape(CLOSE)
}

let debugTriangles = (doodle) => {
  stroke(0, 255, 0)
  strokeWeight(1)
  for (let triangle of doodle.triangles) {
    // fill(random(255), random(255), random(255), 30)
    drawPoly(triangle)
  }
}

let scaleDoodle = (doodle, scale) => {
  let newDrawing = []
  for (let i = 0; i < doodle.drawing.length; i++) {
    let stroke = doodle.drawing[i]
    let newStroke = [[], []]
    for (let j = 0; j < stroke[0].length; j++) {
      newStroke[0].push(stroke[0][j] * scale)
      newStroke[1].push(stroke[1][j] * scale)
    }
    newDrawing.push(newStroke)
  }
  return newDrawing
}

let rotateDoodle = (doodle, angle) => {
  let newDrawing = []
  // Rotate around the center of the bounding box
  let bbox = doodle.bbox
  let cx = (bbox.minX + bbox.maxX) / 2
  let cy = (bbox.minY + bbox.maxY) / 2
  for (let i = 0; i < doodle.drawing.length; i++) {
    let stroke = doodle.drawing[i]
    let newStroke = [[], []]
    for (let j = 0; j < stroke[0].length; j++) {
      let x = stroke[0][j]
      let y = stroke[1][j]
      let dx = x - cx
      let dy = y - cy
      let newX = dx * cos(angle) - dy * sin(angle) + cx
      let newY = dx * sin(angle) + dy * cos(angle) + cy
      newStroke[0].push(newX)
      newStroke[1].push(newY)
    }
    newDrawing.push(newStroke)
  }
  return newDrawing
}

let translateDoodle = (doodle, xOff, yOff) => {
  let newDrawing = []
  for (let i = 0; i < doodle.drawing.length; i++) {
    let stroke = doodle.drawing[i]
    let newStroke = [[], []]
    for (let j = 0; j < stroke[0].length; j++) {
      newStroke[0].push(stroke[0][j] + xOff)
      newStroke[1].push(stroke[1][j] + yOff)
    }
    newDrawing.push(newStroke)
  }
  return newDrawing
}

let getBBox = (drawing) => {
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (let i = 0; i < drawing.length; i++) {
    let stroke = drawing[i]
    for (let j = 0; j < stroke[0].length; j++) {
      let x = stroke[0][j]
      let y = stroke[1][j]
      if (x < minX) minX = x
      if (x > maxX) maxX = x
      if (y < minY) minY = y
      if (y > maxY) maxY = y
    }
  }
  return { minX, minY, maxX, maxY }
}

let generateDoodle = () => {
  let doodle = getRandomDoodle()
  if (doodle) {
    doodles.push(doodle)
  }
  return doodle
}

let generateTriangles = (doodle) => {
  let drawing = doodle.drawing
  let triangles = []
  for (let i = 0; i < drawing.length; i++) {
    let strokeData = drawing[i]
    let xPoints = strokeData[0]
    let yPoints = strokeData[1]

    if (xPoints.length > 2) {
      let points = []
      let convexPolygons

      for (let p = 0; p < xPoints.length; p++) {
        points.push([xPoints[p], yPoints[p]])
      }

      decomp.makeCCW(points)
      if (decomp.isSimple(points)) {
        convexPolygons = decomp.quickDecomp(points)
      } else {
        // Not a simple polygon, use the bounding box
        let minX = Infinity
        let minY = Infinity
        let maxX = -Infinity
        let maxY = -Infinity
        for (let p = 0; p < xPoints.length; p++) {
          let x = xPoints[p]
          let y = yPoints[p]
          if (x < minX) minX = x
          if (x > maxX) maxX = x
          if (y < minY) minY = y
          if (y > maxY) maxY = y
        }
        convexPolygons = [
          [
            [minX, minY],
            [maxX, minY],
            [maxX, maxY],
            [minX, maxY],
          ],
        ]
      }
      // Decompose the convexPolygons into triangles
      let t = convexPolygons.map((p) => triangulate(p)).flat()
      triangles.push(t)
    }
  }
  return triangles.flat(1)
}

let drawDoodle = (doodle, strokeIndex = null) => {
  noFill()
  stroke(doodle.color)
  let baseStrokeWeight = map(doodle.bbox.maxX - doodle.bbox.minX, 25, 255, 4, 10, true)
  let maxStroke = strokeIndex === null ? doodle.drawing.length : strokeIndex
  maxStroke = min(maxStroke, doodle.drawing.length)

  let drawing = doodle.drawing
  for (let i = 0; i < maxStroke; i++) {
    let strokeData = drawing[i]
    let xPoints = strokeData[0]
    let yPoints = strokeData[1]
    for (let p = 0; p < xPoints.length - 1; p++) {
      let x1 = xPoints[p]
      let y1 = yPoints[p]
      let x2 = xPoints[p + 1]
      let y2 = yPoints[p + 1]

      strokeWeight(baseStrokeWeight * random(0.8, 1.2))
      scribble.scribbleLine(x1, y1, x2, y2)
    }
  }
  if (DEBUG) {
    debugTriangles(doodle)
  }
}

function isConvex(a, b, c) {
  // Check if the angle ABC is convex (i.e., the triangle ABC is in counter-clockwise order)
  return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]) > 0
}

function isPointInTriangle(p, a, b, c) {
  // Check if point p is inside triangle ABC
  let w1 =
    (a[0] * (c[1] - a[1]) +
      (p[1] - a[1]) * (c[0] - a[0]) -
      p[0] * (c[1] - a[1])) /
    ((b[1] - a[1]) * (c[0] - a[0]) - (b[0] - a[0]) * (c[1] - a[1]))
  let w2 = (p[1] - a[1] - w1 * (b[1] - a[1])) / (c[1] - a[1])

  return w1 >= 0 && w2 >= 0 && w1 + w2 <= 1
}

function triangulate(polygon) {
  const triangles = []
  const n = polygon.length
  if (n < 3) return triangles // Not a valid polygon
  const remaining = polygon.slice() // Copy of the polygon vertices
  let i = 0

  let _wG_2 = 0; while ((remaining.length > 3) && ++_wG_2 < 20000) {
    let a = remaining[i % remaining.length]
    let b = remaining[(i + 1) % remaining.length]
    let c = remaining[(i + 2) % remaining.length]

    if (isConvex(a, b, c)) {
      let earFound = true

      // Check if any point is inside the potential ear triangle
      for (let j = 0; j < remaining.length; j++) {
        if (
          j !== i &&
          j !== (i + 1) % remaining.length &&
          j !== (i + 2) % remaining.length
        ) {
          if (isPointInTriangle(remaining[j], a, b, c)) {
            earFound = false
            break
          }
        }
      }

      if (earFound) {
        // Clip the ear (add triangle and remove middle vertex)
        triangles.push([a, b, c])
        remaining.splice((i + 1) % remaining.length, 1) // Remove b
        i = 0 // Restart the search
      } else {
        break
      }
    }
    i++
  }

  // Add the final triangle
  triangles.push([remaining[0], remaining[1], remaining[2]])
  return triangles
}

function getLineOrientation(p, q, r) {
  let val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
  if (val === 0) return 0 // Collinear
  return val > 0 ? 1 : 2 // Clockwise or Counterclockwise
}

// Check if point q lies on line segment pr
function onSegment(p, q, r) {
  return (
    q[0] <= Math.max(p[0], r[0]) &&
    q[0] >= Math.min(p[0], r[0]) &&
    q[1] <= Math.max(p[1], r[1]) &&
    q[1] >= Math.min(p[1], r[1])
  )
}

function doLinesIntersect(p1, q1, p2, q2) {
  // Find the 4 orientations needed for general and special cases
  let o1 = getLineOrientation(p1, q1, p2)
  let o2 = getLineOrientation(p1, q1, q2)
  let o3 = getLineOrientation(p2, q2, p1)
  let o4 = getLineOrientation(p2, q2, q1)

  // General case
  if (o1 !== o2 && o3 !== o4) return true

  // Special cases: check if the points are collinear and lie on the segment
  if (o1 === 0 && onSegment(p1, p2, q1)) return true
  if (o2 === 0 && onSegment(p1, q2, q1)) return true
  if (o3 === 0 && onSegment(p2, p1, q2)) return true
  if (o4 === 0 && onSegment(p2, q1, q2)) return true

  return false
}

// Function to check if two triangles overlap
function trianglesOverlap(tri1, tri2) {
  // Extract the vertices of the triangles
  let [a1, b1, c1] = tri1
  let [a2, b2, c2] = tri2

  // Step 0: Check if the bounding boxes of the triangles overlap
  let minAx = min(a1[0], b1[0], c1[0])
  let maxAx = max(a1[0], b1[0], c1[0])
  let minBx = min(a2[0], b2[0], c2[0])
  let maxBx = max(a2[0], b2[0], c2[0])
  let minAy = min(a1[1], b1[1], c1[1])
  let maxAy = max(a1[1], b1[1], c1[1])
  let minBy = min(a2[1], b2[1], c2[1])
  let maxBy = max(a2[1], b2[1], c2[1])
  if (maxAx < minBx || maxBx < minAx || maxAy < minBy || maxBy < minAy) {
    return false
  }

  // Step 1: Check if any vertex of triangle 1 is inside triangle 2
  if (
    isPointInTriangle(a1, a2, b2, c2) ||
    isPointInTriangle(b1, a2, b2, c2) ||
    isPointInTriangle(c1, a2, b2, c2)
  ) {
    return true
  }

  // Step 2: Check if any vertex of triangle 2 is inside triangle 1
  if (
    isPointInTriangle(a2, a1, b1, c1) ||
    isPointInTriangle(b2, a1, b1, c1) ||
    isPointInTriangle(c2, a1, b1, c1)
  ) {
    return true
  }

  // Step 3: Check if any edges of the triangles intersect
  let edges1 = [
    [a1, b1],
    [b1, c1],
    [c1, a1],
  ]
  let edges2 = [
    [a2, b2],
    [b2, c2],
    [c2, a2],
  ]

  for (let [p1, q1] of edges1) {
    for (let [p2, q2] of edges2) {
      if (doLinesIntersect(p1, q1, p2, q2)) {
        return true
      }
    }
  }

  // If none of the above conditions were true, the triangles do not overlap
  return false
}

let texture
function granulate(grainAmount) {
  let gc = createGraphics(cw, ch)
  gc?.loadPixels?.()
  let d = gc.pixelDensity()
  let halfImage = 4 * (cw * d) * (cw * d)
  for (let ii = 0; ii < halfImage; ii += 4) { // noprotect
    gc.pixels[ii] = 255
    gc.pixels[ii + 1] = 255
    gc.pixels[ii + 2] = 255
    gc.pixels[ii + 3] = random(grainAmount)
  }
  gc.updatePixels()
  return gc
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

